import numpy as np

def stable_stats(prices):
    if len(prices) < 2:
        raise ValueError('need at least two prices')
    mean, m2, n = 0.0, 0.0, 0
    for x in prices:
        n += 1
        d = x - mean
        mean += d / n
        m2 += d * (x - mean)
    return (mean, m2 / (n - 1))

def kahan_total(pnl):
    total, c = 0.0, 0.0
    for x in pnl:
        y = x - c
        t = total + y
        c = (t - total) - y
        total = t
    return total
